content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_booth_break",
 "name": "Deadball: the booth, at the stretch",
 "set": "set_hughson_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "none",
    "cut": "dissolve"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Six and a half done. {away} {awayScore}, {home} {homeScore}, and it's time for the stretch.",
     "We're at the stretch. {away} {awayScore}, {home} {homeScore}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{leader} have been the better side. Three innings is a long time, though.",
     "{trailer} need runs, and they're running out of outs to get them."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "tied",
     "op": "=",
     "value": "false"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "All square after six and a half. It's going to come down to the bullpens.",
     "Tied up. Whoever blinks first loses this one."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "tied",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{homersSaid} today. {lastHomer.name} hit the last one, in the {lastHomer.inning}."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "homerCount",
     "op": ">",
     "value": 0
    },
    {
     "fact": "lastHomer.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Stand up and stretch. Let's go to the desk.",
     "We'll send it back to the desk while they sing."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE PARK",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  }
 ]
}
